#[cfg(test)]
mod tests {
    //! Every slot of every console object the layer makes, against the
    //! driver's table above.
    use super::*;
    use crate::object;

    type Get = fn() -> &'static [*const ()];
    /// The layer's tables (the newer layouts, which are the driver's) by
    /// interface, with the object kind their placeholders log as.
    fn tables() -> Vec<(&'static str, &'static [Slot], Get, fn(*const (), usize) -> bool)> {
        vec![
            ("device", &DEVICE, || &crate::device::FUNCTIONS.0, object::is_missing::<{ object::DEVICE }>),
            ("queue", &QUEUE, || &crate::queue::NEWER_FUNCTIONS.0, object::is_missing::<{ object::QUEUE }>),
            ("list", &LIST, || &crate::list::NEWER_LIST_FUNCTIONS.0, object::is_missing::<{ object::LIST }>),
            ("allocator", &ALLOCATOR, || &crate::list::ALLOCATOR_FUNCTIONS.0, object::is_missing::<{ object::ALLOCATOR }>),
            ("pipeline", &PIPELINE, || &crate::pipeline::FUNCTIONS.0, object::is_missing::<{ object::PIPELINE }>),
            ("descriptor heap", &DESCRIPTOR_HEAP, || &crate::descriptor::FUNCTIONS.0, object::is_missing::<{ object::DESCRIPTOR_HEAP }>),
            ("root signature", &ROOT_SIGNATURE, || &crate::root::FUNCTIONS.0, object::is_missing::<{ object::ROOT_SIGNATURE }>),
            ("resource", &RESOURCE, || &crate::resource::RESOURCE_FUNCTIONS.0, object::is_missing::<{ object::RESOURCE }>),
            ("heap", &HEAP, || &crate::resource::HEAP_FUNCTIONS.0, object::is_missing::<{ object::HEAP }>),
            ("fence", &FENCE, || &crate::fence::FUNCTIONS.0, object::is_missing::<{ object::FENCE }>),
            ("query heap", &QUERY_HEAP, || &crate::query::FUNCTIONS.0, object::is_missing::<{ object::QUERY_HEAP }>),
            ("command signature", &COMMAND_SIGNATURE, || &crate::signature::FUNCTIONS.0, object::is_missing::<{ object::COMMAND_SIGNATURE }>),
        ]
    }

    /// Every method the driver only answers a constant from answers it here
    /// (called through the layer's table, as a title calls it), but for the
    /// methods of the layer's own [`OWN_AT_CONSTANT`] names and says why.
    /// (Function addresses are not compared: thin LTO folds and copies them.)
    #[test]
    fn constant_methods_answer_as_the_driver() {
        for (name, spec, table, missing) in tables() {
            let t = table();
            for (i, s) in spec.iter().enumerate() {
                let Kind::Const(v) = s.kind else { continue };
                if OWN_AT_CONSTANT.iter().any(|&(n, o, _)| n == name && o == i * 8) {
                    continue;
                }
                let f = *t.get(i).unwrap_or_else(|| panic!("{name} slot {:#x} beyond the table", i * 8));
                assert!(!missing(f, i), "{name} slot {:#x} (driver +{:#x}) not written", i * 8, s.rva);
                // SAFETY: not one of the layer's own methods: a stub, which
                // reads no arguments.
                let call: extern "system" fn() -> u32 = unsafe { std::mem::transmute(f) };
                assert_eq!(call(), v, "{name} slot {:#x} (driver +{:#x})", i * 8, s.rva);
            }
        }
    }

    /// Every void method of the driver's is written (its stub returns at once).
    #[test]
    fn void_methods_are_written() {
        for (name, spec, table, missing) in tables() {
            let t = table();
            for (i, s) in spec.iter().enumerate() {
                if s.kind == Kind::Void {
                    let f = *t.get(i).unwrap_or_else(|| panic!("{name} slot {:#x} beyond the table", i * 8));
                    assert!(!missing(f, i), "{name} slot {:#x} (driver +{:#x}) not written", i * 8, s.rva);
                }
            }
        }
    }

    /// The driver's methods with bodies that the layer has not written are
    /// exactly [`NOT_WRITTEN`]: a slot written makes this fail until it is
    /// taken off, so the list stays what is left to do.
    #[test]
    fn methods_not_written_are_known() {
        let mut gaps = Vec::new();
        for (name, spec, table, missing) in tables() {
            let t = table();
            for (i, s) in spec.iter().enumerate() {
                if s.kind != Kind::Body {
                    continue;
                }
                if t.get(i).is_none_or(|&f| missing(f, i)) {
                    gaps.push((name, i * 8));
                }
            }
        }
        let known: Vec<(&str, usize)> = NOT_WRITTEN.iter().map(|&(n, s)| (n, s)).collect();
        let named: Vec<String> = gaps
            .iter()
            .map(|&(n, o)| if n == "list" { format!("{n} {o:#x} {}", LIST_NAMES[o / 8]) } else { format!("{n} {o:#x}") })
            .collect();
        assert_eq!(gaps, known, "not written now: {named:?}");
    }

    /// Every table is at least as long as the driver's, so a call to its
    /// last method lands in the table.
    #[test]
    fn tables_are_as_long_as_the_drivers() {
        for (name, spec, table, _) in tables() {
            assert!(table().len() >= spec.len(), "{name}: {} slots, the driver's {}", table().len(), spec.len());
        }
    }
}

